class ErrorBoundary extends Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false };
  }
  static getDerivedStateFromError() {
    return { hasError: true };
  }
  componentDidCatch(err) {
    console.error("KimchiShop crashed:", err);
  }
  render() {
    if (this.state.hasError) {
      return (
        <div style={{ background: THEME.bg, minHeight: 300, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", fontFamily: FONT_SANS, color: THEME.paper, padding: 24, textAlign: "center", gap: 12 }}>
          <div style={{ fontFamily: FONT_VOICE, fontSize: 22 }}>Something went wrong</div>
          <div style={{ color: THEME.paperMuted, fontSize: 14, maxWidth: 360 }}>
            Sorry about that! Please try reloading. Your order data is saved and won't be lost.
          </div>
          <Button onClick={() => this.setState({ hasError: false })}>Try again</Button>
        </div>
      );
    }
    return this.props.children;
  }
}

